#!/usr/bin/env python3
"""Generate User Certificate DTOs and source-bound operation contracts offline."""
from pathlib import Path
import json,re,subprocess,hashlib
ROOT=Path(__file__).resolve().parents[2]
source=json.loads((ROOT/'catalog/sources/certificates-manager.json').read_text())
names={key:key.removeprefix('rest.') for key in source['definitions'] if key.startswith('rest.')}
acronyms={'id':'ID','dns':'DNS','pem':'PEM','pkcs12':'PKCS12'}
def field_name(value):
 words=re.sub(r'([a-z])([A-Z])',r'\1_\2',value).split('_')
 return ''.join(acronyms.get(word.lower(),word[0].upper()+word[1:]) for word in words)
def go_type(schema,property_name=''):
 if '$ref' in schema:return names[schema['$ref'].split('/')[-1]]
 if 'allOf' in schema:return go_type(schema['allOf'][0])
 kind=schema.get('type')
 if kind=='array':return '[]'+go_type(schema['items'])
 if kind=='integer':return 'types.Integer'
 if kind=='boolean':return 'bool'
 if kind=='string':return 'types.ProtectedValue' if property_name=='private_key' else 'string'
 raise ValueError(schema)
lines=['// Code generated by certificategen; DO NOT EDIT.','package certificates','import "github.com/festy23/selectel-sdk/types"']
for key,name in names.items():
 lines.append('type '+name+' struct{')
 if name=='Certificate':lines.append('Ref types.ResourceRef `json:"ref"`')
 for prop,schema in source['definitions'][key].get('properties',{}).items():
  t=go_type(schema,prop);prefix='' if t.startswith('[]') and name not in ['PEMCertificate','UpdateCertificateConsumerRequest'] else '*'
  lines.append(field_name(prop)+' '+prefix+t+' `json:"'+prop+',omitempty"`')
 lines.append('}')
lines.extend(['type DeleteOptions struct{Force *bool `json:"force,omitempty"`}','type wirePEM struct{Certificates *[]string `json:"certificates,omitempty"`;PrivateKey *string `json:"private_key,omitempty"`}','type wireVersion struct{PEM *wirePEM `json:"pem,omitempty"`}','type wireUpload struct{Name *string `json:"name,omitempty"`;PEM *wirePEM `json:"pem,omitempty"`}'])
p=ROOT/'certificates/types_generated.go';p.write_text('\n'.join(lines)+'\n');subprocess.run(['gofmt','-w',str(p)],check=True)
# A binding is added only when the public method and transport evidence exist.
operation='certificates.user_v1.certificates.get'
