b[operation]={'go_method':'certificates.Upload','input_type':'certificates.UploadCertificateRequest, types.CallOptions','output_type':'certificates.Certificate','status':'implemented','contract_ref':f'contracts/{operation}.json','covered_schema_ref':f'contracts/{operation}.json#/request','excluded_variants':[],'files':['client.go','certificates/client.go','certificates/mutations.go','certificates/types_generated.go','internal/certificategen/generate.py','internal/core/reads.go','internal/core/request.go','internal/core/auth.go','generate.go'],'evidence_files':['certificates/client_public_test.go'],'evidence_ref':'certificates/client_public_test.go','recovery':False,'wait_goals':[]}
(ROOT/'catalog/bindings.json').write_text(json.dumps(b,indent=2)+'\n')

