(ROOT/'catalog/contracts'/f'{operation}.json').write_text(json.dumps(contract,indent=2)+'\n')
b[operation]={'go_method':'certificates.List','input_type':'pagination.Options','output_type':'pagination.Iterator[certificates.Certificate]','status':'implemented','contract_ref':f'contracts/{operation}.json','covered_schema_ref':f'contracts/{operation}.json#/request','excluded_variants':[],'files':['client.go','certificates/client.go','certificates/list.go','certificates/types_generated.go','internal/certificategen/generate.py','internal/core/reads.go','internal/core/request.go','internal/core/auth.go','pagination/pagination.go','generate.go'],'evidence_files':['certificates/client_public_test.go'],'evidence_ref':'certificates/client_public_test.go','recovery':False,'wait_goals':[]}
(ROOT/'catalog/bindings.json').write_text(json.dumps(b,indent=2)+'\n')

# Every response shape absent from OpenAPI is pinned to licensed SDK evidence.
assets={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((ROOT/'internal/certificategen/assets').iterdir(),key=lambda p:p.name) if p.is_file()}
for operation,entry in b.items():
 if not operation.startswith('certificates.user_v1.'):continue
 path=ROOT/'catalog/contracts'/f'{operation}.json'
 contract=json.loads(path.read_text())
 contract['source_evidence']={'openapi_uri':'https://docs.selectel.ru/api/certificates-manager.json','openapi_sha256':hashlib.sha256((ROOT/'catalog/sources/certificates-manager.json').read_bytes()).hexdigest(),'sdk_commit':'5adf32225d3863ae40fd351ea33629f3fcca2447','sdk_assets_sha256':assets}
 if operation.endswith('.delete'):
  contract['request']['mapping']='Exact certificate ref and optional force query; nil omitted, explicit false/true retained; no body. Force is never selected automatically.'
 if operation in ['certificates.user_v1.consumers.add','certificates.user_v1.consumers.remove']:
  contract['request']['mapping']='All documented flat id/region/type and optional consumers array fields retained, including explicit empty arrays; consumer attributes remain opaque provider identifiers, no scope/adoption inferred. Request DTO contains no SDK refs.'
 contract['recovery']='Root Resource/Resume validate account/project/generation/kind/endpoint, operation/effect/revision and receipt/ref agreement. Metadata Get observes exact address only. Unknown remains indeterminate; no name lookup/adoption/replay. Known no-ref terminal receipt Recover conclusive without I/O; no resource state/wait inferred.'
 contract['wait']={'goals':[]}
